import 'package:flutter/material.dart';import '../data/repositories/expense_repository.dart';
class CategoriesScreen extends StatefulWidget{const CategoriesScreen({super.key,required this.onChanged});final VoidCallback onChanged;@override State<CategoriesScreen> createState()=>_CategoriesScreenState();}
class _CategoriesScreenState extends State<CategoriesScreen>{final repo=ExpenseRepository();String type='expense';late Future<List<Map<String,Object?>>> future;@override void initState(){super.initState();future=repo.categories(type:type);}void reload()=>setState(()=>future=repo.categories(type:type));
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Categories')),body:Column(children:[Padding(padding:const EdgeInsets.all(14),child:SegmentedButton<String>(segments:const[ButtonSegment(value:'expense',label:Text('Expense')),ButtonSegment(value:'income',label:Text('Income'))],selected:{type},onSelectionChanged:(v){setState(()=>type=v.first);reload();})),Expanded(child:FutureBuilder<List<Map<String,Object?>>>(future:future,builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());return ListView(children:s.data!.map((e)=>ListTile(leading:const CircleAvatar(child:Icon(Icons.label_outline)),title:Text(e['name'] as String),subtitle:Text((e['is_default'] as int)==1?'Default':'Custom'))).toList());}))]),floatingActionButton:FloatingActionButton.extended(onPressed:add,icon:const Icon(Icons.add),label:const Text('Add category')));
 Future<void> add()async{final name=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('New category'),content:TextField(controller:name,decoration:const InputDecoration(labelText:'Name')),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancel')),TextButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Save'))]));if(ok==true&&name.text.trim().isNotEmpty){await repo.addCategory(name.text.trim(),type);widget.onChanged();reload();}name.dispose();}
}
